import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer
import kotlin.math.min
import kotlin.math.max

private class FastScanner {
    private val reader = BufferedReader(InputStreamReader(System.`in`))
    private var tokenizer = StringTokenizer("")

    fun next(): String {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = StringTokenizer(reader.readLine())
        }
        return tokenizer.nextToken()
    }

    fun nextInt(): Int = next().toInt()
}

fun main() {
    val input = FastScanner()
    val n = input.nextInt()
    val k = input.nextInt()
    val s = input.next()
    val t = input.next()

    if (t[0] == t[1]) {
        val x = min(s.count { it == t[0] } + k, n)
        println(x * (x - 1) / 2)
        return
    }

    val f = Array(n + 2) {
        Array(n + 2) {
            IntArray(n + 2) { -100_000 }
        }
    }
    f[0][0][0] = 0

    for (i in 0..n) {
        for (j in 0..k) {
            for (cnt0 in 0..i) {
                if (f[i][j][cnt0] < 0) continue

                val e0 = if (i < n && s[i] == t[0]) 1 else 0
                val e1 = if (i < n && s[i] == t[1]) 1 else 0

                f[i + 1][j][cnt0 + e0] = max(
                    f[i + 1][j][cnt0 + e0],
                    f[i][j][cnt0] + e1 * cnt0
                )
                f[i + 1][j + 1][cnt0 + 1] = max(
                    f[i + 1][j + 1][cnt0 + 1],
                    f[i][j][cnt0]
                )
                f[i + 1][j + 1][cnt0] = max(
                    f[i + 1][j][cnt0],
                    f[i][j][cnt0] + cnt0
                )
            }
        }
    }

    var answer = Int.MIN_VALUE
    for (i in 0..k) {
        for (j in 0..n) {
            answer = max(answer, f[n][i][j])
        }
    }
    println(answer)
}

